import math


def masked_row_means(values, mask):
    if not isinstance(values, list) or not isinstance(mask, list):
        raise TypeError("arguments must be lists")
    if len(values) != len(mask):
        raise ValueError("row counts differ")
    width = len(values[0]) if values else 0
    result = []
    for value_row, mask_row in zip(values, mask):
        if not isinstance(value_row, list) or not isinstance(mask_row, list):
            raise TypeError("rows must be lists")
        if len(value_row) != width or len(mask_row) != width:
            raise ValueError("inputs must have identical rectangular shapes")
        total = 0.0
        count = 0
        for value, selected in zip(value_row, mask_row):
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("values must be numeric")
            if not math.isfinite(value):
                raise ValueError("values must be finite")
            if type(selected) is not bool:
                raise TypeError("mask entries must be booleans")
            if selected:
                total += value
                count += 1
        result.append(total / len(value_row) if count else None)
    return tuple(result)

